int isSafe(int *board, int row, int col) {
    for (int i = 0; i < row; i++) {
        if (board[i] == col || abs(board[i] - col) == abs(i - row)) {
            return 0;
        }
    }
    return 1;
}

void solveNQueensUtil(int n, int row, int *board, int *count) {
    if (row == n) {
        (*count)++;
        return;
    }
    for (int col = 0; col < n; col++) {
        if (isSafe(board, row, col)) {
            board[row] = col;
            solveNQueensUtil(n, row + 1, board, count);
        }
    }
}

int totalNQueens(int n) {
    if (n <= 0) return 0;
    int *board = (int *)malloc(n * sizeof(int));
    if (!board) return -1;
    memset(board, -1, n * sizeof(int));
    int count = 0;
    solveNQueensUtil(n, 0, board, &count);
    free(board);
    return count;
}

