typedef enum {
    SET_BIT,
    UNSET_BIT,
    TOGGLE_BIT
} BitOperation;

void bit_operation(int *num, BitOperation op, int bit_pos) {
    if (bit_pos < 0 || bit_pos >= (int)(sizeof(int) * 8)) {
        printf("Error: Bit position %d out of range.\n", bit_pos);
        return;
    }

    // Target Bug: Invalid pointer cast from int* to char*
    // This cast is incorrect because it assumes char* points to the same memory layout as int*,
    // leading to potential misalignment and undefined behavior when dereferencing.
    char *byte_ptr = (char *)num;  // Bug: Casting int* to char* without proper handling

    // Attempt to access the specific byte containing the bit
    int byte_index = bit_pos / 8;
    int bit_in_byte = bit_pos % 8;

    // Dereferencing byte_ptr after invalid cast can cause issues
    char target_byte = byte_ptr[byte_index];  // Potential misalignment or segfault

    switch (op) {
        case SET_BIT:
            target_byte |= (1 << bit_in_byte);
            break;
        case UNSET_BIT:
            target_byte &= ~(1 << bit_in_byte);
            break;
        case TOGGLE_BIT:
            target_byte ^= (1 << bit_in_byte);
            break;
        default:
            printf("Error: Invalid operation.\n");
            return;
    }

    // Write back the modified byte
    byte_ptr[byte_index] = target_byte;
}

int main() {
    // Example usage
    int value = 0;  // Binary: 0000...0000

    printf("Initial value: %d\n", value);

    bit_operation(&value, SET_BIT, 3);  // Should set bit 3 to 1
    printf("After setting bit 3: %d\n", value);

    bit_operation(&value, TOGGLE_BIT, 3);  // Should toggle bit 3 back to 0
    printf("After toggling bit 3: %d\n", value);

    bit_operation(&value, UNSET_BIT, 5);  // Should unset bit 5 (already 0)
    printf("After unsetting bit 5: %d\n", value);

    return 0;
}

