void print_last_n_lines(char *lines[], int n) {
    int total_lines = sizeof(lines) / sizeof(lines[0]);
    int start_index;

    if (n <= 0) {
        return;
    }

    if (n > total_lines) {
        start_index = 0;
    } else {
        start_index = total_lines - n;
    }

    for (int i = start_index; i < total_lines; i++) {
        printf("%s\n", lines[i]);
    }
}

