    new_node->next = NULL;
    return new_node;
}

int get_at_index(Node* head, int index) {
    Node* current = head;
    int count = 1;  // Bug: Should start at 0 for 0-based indexing

    while (current != NULL) {
        if (count == index) {  // Bug: Compares count with index, but count starts at 1
            return current->data;
        }
        current = current->next;
        count++;
    }

    return -1;  // Index out of bounds
}

