void flood_fill(char **grid, int rows, int cols, int x, int y, char target_char, char new_char) {
    if (x < 0 || x >= rows || y < 0 || y >= cols) {
        return;
    }
    if (grid[x][y] != target_char) {
        return;
    }

    grid[x][y] = new_char;

    int rows = rows;  // Shadowing variable: local 'rows' hides parameter 'rows'
    int cols = cols;  // Shadowing variable: local 'cols' hides parameter 'cols'

    flood_fill(grid, rows, cols, x + 1, y, target_char, new_char);
    flood_fill(grid, rows, cols, x - 1, y, target_char, new_char);
    flood_fill(grid, rows, cols, x, y + 1, target_char, new_char);
    flood_fill(grid, rows, cols, x, y - 1, target_char, new_char);
}

int main() {
    // Example usage for testing
    int rows = 5, cols = 5;
    char **grid = (char **)malloc(rows * sizeof(char *));
    for (int i = 0; i < rows; i++) {
        grid[i] = (char *)malloc(cols * sizeof(char));
        for (int j = 0; j < cols; j++) {
            grid[i][j] = '.';
        }
    }

    // Set a region to fill
    grid[1][1] = 'X';
    grid[1][2] = 'X';
    grid[2][1] = 'X';
    grid[2][2] = 'X';

